function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }

  const parts = text.split(/(\r\n|\n|\r)/);
  return parts
    .map((part, index) => {
      if (index % 2 !== 0 || (part === '' && index === parts.length - 1)) {
        return part;
      }
      return part.trim() === '' ? '>' : `> ${part}`;
    })
    .join('');
}
